&lt;p&gt;&lt;span class="EOP SCXW446762 BCX0" data-ccp-props="{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559685&amp;quot;:360}"&gt;&lt;span class="TextRun SCXW169101435 BCX0" lang="EN-US" data-contrast="auto"&gt;&lt;span class="NormalTextRun SCXW169101435 BCX0" data-ccp-parastyle="Normal (Web)"&gt;&lt;span style="color: rgb(224, 62, 45);"&gt;&lt;strong&gt;} } ;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;
